//! The list-marker Chrome 156 control (`tests/fixtures/list_markers_chrome156.json`,
//! generated by turbo-dom's `scripts/list-marker-chrome-control.mjs`;
//! miaskiewicz/turbo-dom#128), laid out through the live HTML snapshot in the fixture
//! fonts: each `[data-cid]` element's border box, each list item's `::marker` box (the
//! snapshot fragment whose `list_marker_owner` is the item: an outside marker's box, an
//! inside text marker's run) and, for `[data-text]` items, where their text starts.
//! An inside marker is compared by its inline extent only (Chrome reports an inline
//! box's content area as its height; the snapshot's box is the line's).
use serde_json::Value;

use super::source_id;
use super::testing::{layout_with_fonts, DOCUMENT};
use crate::cssom_view::{metrics, text};
use crate::layout_snapshot::{GeometryKind, LayoutSnapshot, Rect, SourceId};

const FIXTURE: &str = include_str!("../../tests/fixtures/list_markers_chrome156.json");

fn css_of(html: &str) -> &str {
    html.split_once("<style>")
        .and_then(|(_, rest)| rest.split_once("</style>"))
        .map_or("", |(css, _)| css)
}

/// A length to 1/16 px (summed glyph advances differ from Blink's `LayoutUnit`s by up
/// to about 1/64 px).
fn unit(v: f64) -> f64 {
    (v * 16.0).round() / 16.0
}

fn rect_text(rect: [f64; 4], inline_only: bool) -> String {
    if inline_only {
        format!("x {} width {}", unit(rect[0]), unit(rect[2]))
    } else {
        format!("{:?}", rect.map(unit))
    }
}

fn ours(rect: Rect) -> [f64; 4] {
    [rect.x, rect.y, rect.width, rect.height].map(f64::from)
}

fn chrome(value: &Value) -> [f64; 4] {
    let n = |i: usize| value[i].as_f64().unwrap();
    [n(0), n(1), n(2), n(3)]
}

/// The marker rects of the list item `owner`: its marker box, else (an inside text
/// marker) its marker text run.
fn marker_rects(snapshot: &LayoutSnapshot, owner: SourceId) -> Vec<[f64; 4]> {
    let mine = |index: usize| snapshot.list_marker_owner(index) == Some(owner);
    let boxes: Vec<[f64; 4]> = snapshot
        .fragments()
        .iter()
        .filter(|f| f.kind == GeometryKind::BorderBox && mine(f.index))
        .filter(|f| f.parent.is_none_or(|p| !mine(p)))
        .map(|f| ours(f.rect))
        .collect();
    if !boxes.is_empty() {
        return boxes;
    }
    snapshot
        .text_runs()
        .iter()
        .filter(|run| mine(run.fragment_index))
        .filter_map(|run| text::run_rect(snapshot, run))
        .map(ours)
        .collect()
}

/// Where the first text run of the list item `item` starts.
fn text_start(
    snapshot: &LayoutSnapshot,
    tree: &turbo_dom::Tree,
    item: turbo_dom::Handle,
) -> Option<f64> {
    let text = tree
        .children(item)
        .into_iter()
        .find(|&h| tree.local_name(h).is_none())?;
    let id = source_id(DOCUMENT, text);
    snapshot
        .text_runs()
        .iter()
        .filter(|run| run.source_id == Some(id))
        .find_map(|run| text::run_rect(snapshot, run))
        .map(|rect| f64::from(rect.x))
}

/// Every read of `case`, as `(ours, Chrome's)` lines.
fn reads(case: &Value) -> (Vec<String>, Vec<String>) {
    let name = case["id"].as_str().unwrap();
    let html = case["html"].as_str().unwrap();
    let fonts = crate::test_support::fixture_fonts();
    let (tree, snapshot, _) = layout_with_fonts(
        html,
        css_of(html),
        (800.0, 600.0),
        Some(1.0),
        |_| {},
        &fonts,
    );
    let handle = |cid: &str| {
        tree.query_selector(&format!("[data-cid=\"{cid}\"]"))
            .unwrap()
    };
    let (mut got, mut want) = (Vec::new(), Vec::new());
    for b in case["boxes"].as_array().unwrap() {
        let cid = b["cid"].as_str().unwrap();
        let id = source_id(DOCUMENT, handle(cid));
        got.push(format!(
            "{name}: {cid} box {}",
            metrics::element_geometry(&snapshot, id)
                .map_or_else(|e| e, |g| rect_text(ours(g.bounds), false))
        ));
        want.push(format!(
            "{name}: {cid} box {}",
            rect_text(chrome(&b["rect"]), false)
        ));
    }
    let markers = case["markers"].as_array().unwrap();
    for b in case["boxes"].as_array().unwrap() {
        let cid = b["cid"].as_str().unwrap();
        let item = handle(cid);
        if tree.local_name(item) != Some("li") {
            continue;
        }
        let inside = name.starts_with("inside-");
        let mine: Vec<String> = marker_rects(&snapshot, source_id(DOCUMENT, item))
            .into_iter()
            .map(|r| rect_text(r, inside))
            .collect();
        let theirs: Vec<String> = markers
            .iter()
            .filter(|m| m["cid"] == cid)
            .map(|m| rect_text(chrome(&m["rect"]), inside))
            .collect();
        got.push(format!("{name}: {cid} marker {mine:?}"));
        want.push(format!("{name}: {cid} marker {theirs:?}"));
    }
    for t in case["texts"].as_array().into_iter().flatten() {
        let cid = t["cid"].as_str().unwrap();
        got.push(format!(
            "{name}: {cid} text {:?}",
            text_start(&snapshot, &tree, handle(cid)).map(unit)
        ));
        want.push(format!(
            "{name}: {cid} text {:?}",
            Some(unit(t["x"].as_f64().unwrap()))
        ));
    }
    (got, want)
}

#[test]
fn list_markers_match_chrome_156() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    assert!(fixture["chrome"].as_str().unwrap().starts_with("156."));
    let (mut got, mut want) = (Vec::new(), Vec::new());
    for case in fixture["cases"].as_array().unwrap() {
        let (ours, theirs) = reads(case);
        got.extend(ours);
        want.extend(theirs);
    }
    assert_eq!(got.len(), want.len());
    let diff: Vec<String> = got
        .iter()
        .zip(&want)
        .filter(|(a, b)| a != b)
        .map(|(a, b)| format!("ours   {a}\nchrome {b}"))
        .collect();
    assert!(
        diff.is_empty(),
        "list markers differ from Chrome 156:\n{}",
        diff.join("\n")
    );
}

#[test]
fn the_control_covers_every_marker() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    let cases = fixture["cases"].as_array().unwrap();
    let markers: usize = cases
        .iter()
        .map(|c| c["markers"].as_array().unwrap().len())
        .sum();
    assert_eq!((cases.len(), markers), (38, 70));
}
